  __bindings[r_upright_com] = [upright_com[1] - lca_upright[1], upright_com[3] - lca_upright[3], dir * (upright_com[2] - lca_upright[2])]
  __bindings[r_upright_spindle] = [spindle_point[1] - lca_upright[1], spindle_point[3] - lca_upright[3], dir * (spindle_point[2] - lca_upright[2])]
  __bindings[r_spring_chassis] = [spring_chassis[1], spring_chassis[3], dir * spring_chassis[2]]
  __bindings[r_tierod_chassis] = [tierod_chassis[1], tierod_chassis[3], dir * tierod_chassis[2]]
  __bindings[rod_tierod] = [tierod_upright[1] - tierod_chassis[1], tierod_upright[3] - tierod_chassis[3], dir * (tierod_upright[2] - tierod_chassis[2])]

  ### Final Path Parameters

  ### Variables (declarations)

  ### Variables (assignments)

  ### Constants
  __constants = Any[]

  ### Components
  push!(__systems, @named chassis_frame = __Dyad__Frame3D())
  push!(__systems, @named wheel_frame = __Dyad__Frame3D())
  if steered
    push!(__systems, @named steer_frame = __Dyad__Frame3D())
  end
  # Subcomponent lca_mount of type MultibodyComponents.FixedTranslation
  lca_mount_overrides = __pop_subcomponent_overrides!(__overrides, "lca_mount")
  push!(__systems, @named lca_mount = MultibodyComponents.FixedTranslation(; r=r_lca_mid, render=false, __overrides = lca_mount_overrides))
  # Subcomponent lca_rev of type MultibodyComponents.Revolute
  lca_rev_overrides = __pop_subcomponent_overrides!(__overrides, "lca_rev")
  lca_rev_dict = Dict{String, Any}()
  lca_rev_dict["phi.initial"] = ModelingToolkit.default_to_parentscope(lca_phi0)
  lca_rev_dict["w.initial"] = ModelingToolkit.default_to_parentscope(0)
  merge!(lca_rev_dict, lca_rev_overrides)
  push!(__systems, @named lca_rev = MultibodyComponents.Revolute(; n=n_lca, statePriority=100, render=render, __overrides = lca_rev_dict))
  # Subcomponent lca_body of type MultibodyComponents.Body
  lca_body_overrides = __pop_subcomponent_overrides!(__overrides, "lca_body")
  push!(__systems, @named lca_body = MultibodyComponents.Body(; m=lca_m, r_cm=r_lca_com, I_11=lca_inertia[1], I_22=lca_inertia[3], I_33=lca_inertia[2], render=false, __overrides = lca_body_overrides))
  # Subcomponent lca_arm of type MultibodyComponents.FixedTranslation
  lca_arm_overrides = __pop_subcomponent_overrides!(__overrides, "lca_arm")
  push!(__systems, @named lca_arm = MultibodyComponents.FixedTranslation(; r=r_lca_ball, render=render, __overrides = lca_arm_overrides))
  # Subcomponent lca_spring_arm of type MultibodyComponents.FixedTranslation
  lca_spring_arm_overrides = __pop_subcomponent_overrides!(__overrides, "lca_spring_arm")
  push!(__systems, @named lca_spring_arm = MultibodyComponents.FixedTranslation(; r=r_lca_spring, render=render, __overrides = lca_spring_arm_overrides))
  # Subcomponent uca_mount of type MultibodyComponents.FixedTranslation
  uca_mount_overrides = __pop_subcomponent_overrides!(__overrides, "uca_mount")
  push!(__systems, @named uca_mount = MultibodyComponents.FixedTranslation(; r=r_uca_mid, render=false, __overrides = uca_mount_overrides))
  # Subcomponent uca_rev of type MultibodyComponents.Revolute
  uca_rev_overrides = __pop_subcomponent_overrides!(__overrides, "uca_rev")
  if !closed_form
    push!(__systems, @named uca_rev = MultibodyComponents.Revolute(; n=n_uca, render=render, __overrides = uca_rev_overrides))
  end
  # Subcomponent uca_body of type MultibodyComponents.Body
  uca_body_overrides = __pop_subcomponent_overrides!(__overrides, "uca_body")
  push!(__systems, @named uca_body = MultibodyComponents.Body(; m=uca_m, r_cm=r_uca_com, I_11=uca_inertia[1], I_22=uca_inertia[3], I_33=uca_inertia[2], render=false, __overrides = uca_body_overrides))
  # Subcomponent uca_arm of type MultibodyComponents.FixedTranslation
  uca_arm_overrides = __pop_subcomponent_overrides!(__overrides, "uca_arm")
  if !closed_form
    push!(__systems, @named uca_arm = MultibodyComponents.FixedTranslation(; r=r_uca_ball, render=render, __overrides = uca_arm_overrides))
  end
  # Subcomponent lca_ball of type MultibodyComponents.Spherical
  lca_ball_overrides = __pop_subcomponent_overrides!(__overrides, "lca_ball")
  if !closed_form
    lca_ball_dict = Dict{String, Any}()
    lca_ball_dict["phid.initial"] = ModelingToolkit.default_to_parentscope(missing)
    merge!(lca_ball_dict, lca_ball_overrides)
    push!(__systems, @named lca_ball = MultibodyComponents.Spherical(; render=render, initialize_orientation=false, __overrides = lca_ball_dict))
  end
  # Subcomponent upright_body of type MultibodyComponents.Body
  upright_body_overrides = __pop_subcomponent_overrides!(__overrides, "upright_body")
  push!(__systems, @named upright_body = MultibodyComponents.Body(; m=upright_m, r_cm=r_upright_com, I_11=upright_inertia[1], I_22=upright_inertia[3], I_33=upright_inertia[2], render=false, __overrides = upright_body_overrides))
  # Subcomponent upright_to_uca of type MultibodyComponents.FixedTranslation
  upright_to_uca_overrides = __pop_subcomponent_overrides!(__overrides, "upright_to_uca")
  if !closed_form
    push!(__systems, @named upright_to_uca = MultibodyComponents.FixedTranslation(; r=r_upright_uca, render=render, __overrides = upright_to_uca_overrides))
  end
  # Subcomponent upright_to_tierod of type MultibodyComponents.FixedTranslation
  upright_to_tierod_overrides = __pop_subcomponent_overrides!(__overrides, "upright_to_tierod")
  if !closed_form
    push!(__systems, @named upright_to_tierod = MultibodyComponents.FixedTranslation(; r=r_upright_tierod, render=render, __overrides = upright_to_tierod_overrides))
  end
  # Subcomponent upright_to_spindle of type MultibodyComponents.FixedTranslation
  upright_to_spindle_overrides = __pop_subcomponent_overrides!(__overrides, "upright_to_spindle")
  push!(__systems, @named upright_to_spindle = MultibodyComponents.FixedTranslation(; r=r_upright_spindle, render=render, __overrides = upright_to_spindle_overrides))
  # Subcomponent uca_ball of type MultibodyComponents.SphericalConstraint
  uca_ball_overrides = __pop_subcomponent_overrides!(__overrides, "uca_ball")
  if !closed_form
    push!(__systems, @named uca_ball = MultibodyComponents.SphericalConstraint(; render=render, __overrides = uca_ball_overrides))
  end
  # Subcomponent tierod of type MultibodyComponents.SphericalSpherical
  tierod_overrides = __pop_subcomponent_overrides!(__overrides, "tierod")
  if !closed_form
    push!(__systems, @named tierod = MultibodyComponents.SphericalSpherical(; r_0=rod_tierod, render=render, __overrides = tierod_overrides))
  end
  # Subcomponent loop of type SedanDemo.VehicleComponents.DoubleWishboneJoint
  loop_overrides = __pop_subcomponent_overrides!(__overrides, "loop")
  if closed_form
    push!(__systems, @named loop = SedanDemo.VehicleComponents.DoubleWishboneJoint(; n_b=n_uca, rUpper_ib=r_uca_ball, rUpper_ub=r_upright_uca, rTie_ub=r_upright_tierod, rTie_0=rod_tierod, upper_phi_guess=uca_rev_phi0, render=render, __overrides = loop_overrides))
  end
  # Subcomponent tierod_mount of type MultibodyComponents.FixedTranslation
  tierod_mount_overrides = __pop_subcomponent_overrides!(__overrides, "tierod_mount")
  if !steered
    push!(__systems, @named tierod_mount = MultibodyComponents.FixedTranslation(; r=r_tierod_chassis, render=false, __overrides = tierod_mount_overrides))
  end
  # Subcomponent spring_mount of type MultibodyComponents.FixedTranslation
  spring_mount_overrides = __pop_subcomponent_overrides!(__overrides, "spring_mount")
  push!(__systems, @named spring_mount = MultibodyComponents.FixedTranslation(; r=r_spring_chassis, render=false, __overrides = spring_mount_overrides))
  # Subcomponent springdamper of type MultibodyComponents.SpringDamperParallel
  springdamper_overrides = __pop_subcomponent_overrides!(__overrides, "springdamper")
  push!(__systems, @named springdamper = MultibodyComponents.SpringDamperParallel(; c=c_spring, d=d_damper, s_unstretched=s_unstretched, render=render, __overrides = springdamper_overrides))

  ### Check there are no unmatched overrides
  isempty(__overrides) || throw(ArgumentError("overrides: [$(join(keys(__overrides), ", "))] don't match names found in model. These names may exist in the model but could have been conditionally excluded. Override keys are dotted paths as written in Dyad source (e.g. inner.rate)."))

  ### Guesses
  __guesses[lca_rev.phi] = (lca_phi0)

  ### Initialization Equations

  ### Assertions
  __assertions = []

  ### Equations
  push!(__eqs, connect(lca_mount.frame_b, lca_rev.frame_a))
  push!(__eqs, connect(spring_mount.frame_b, springdamper.frame_a))
  push!(__eqs, connect(springdamper.frame_b, lca_spring_arm.frame_b))
  push!(__eqs, connect(upright_to_spindle.frame_b, wheel_frame))
  push!(__eqs, connect(uca_mount.frame_a, chassis_frame))
  push!(__eqs, connect(spring_mount.frame_a, chassis_frame, lca_mount.frame_a))
  push!(__eqs, connect(lca_spring_arm.frame_a, lca_arm.frame_a))
  push!(__eqs, connect(lca_rev.frame_b, lca_arm.frame_a, lca_body.frame_a))

  ### Control Structures
  if !closed_form
    __guesses[lca_ball.phi] = (lca_ball_phi0)
    __guesses[lca_ball.phid] = ([0, 0, 0])
    __guesses[uca_rev.phi] = (uca_rev_phi0)
    __guesses[uca_rev.w] = (0)
    __guesses[tierod.f_rod] = (0)
    __guesses[uca_ball.frame_b.f] = ([0, 0, 0])
  else
  end
  if closed_form
    push!(__eqs, connect(lca_arm.frame_b, loop.frame_a))
    push!(__eqs, connect(uca_mount.frame_b, loop.frame_b))
    push!(__eqs, connect(loop.frame_ub, upright_body.frame_a, upright_to_spindle.frame_a))
    push!(__eqs, connect(loop.frame_ib, uca_body.frame_a))
    if steered
      push!(__eqs, connect(loop.frame_c, steer_frame))
    else
      push!(__eqs, connect(chassis_frame, tierod_mount.frame_a))
      push!(__eqs, connect(tierod_mount.frame_b, loop.frame_c))
    end
  else
    push!(__eqs, connect(uca_mount.frame_b, uca_rev.frame_a))
    push!(__eqs, connect(lca_arm.frame_b, lca_ball.frame_a))
    push!(__eqs, connect(lca_ball.frame_b, upright_body.frame_a, upright_to_uca.frame_a, upright_to_tierod.frame_a, upright_to_spindle.frame_a))
    push!(__eqs, connect(uca_arm.frame_b, uca_ball.frame_a))
    push!(__eqs, connect(uca_ball.frame_b, upright_to_uca.frame_b))
    push!(__eqs, connect(tierod.frame_b, upright_to_tierod.frame_b))
    if steered
      push!(__eqs, connect(tierod.frame_a, steer_frame))
    else
      push!(__eqs, connect(chassis_frame, tierod_mount.frame_a))
      push!(__eqs, connect(tierod_mount.frame_b, tierod.frame_a))
    end
    push!(__eqs, connect(uca_rev.frame_b, uca_arm.frame_a, uca_body.frame_a))
  end

  # Return completely constructed System
  return System(__eqs, ModelingToolkit.t_nounits, __vars, __params; systems=__systems, initial_conditions=__initial_conditions, guesses=__guesses, name, initialization_eqs=__initialization_eqs, bindings=__bindings, assertions=__assertions)
end
export DoubleWishboneSuspension
